//! The embedded catalog: `data/components.json`, generated by `scripts/gen-mcp-data.py` from the
//! gallery's demo registry and the crate sources.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// The raw JSON, compiled into the binary so the server is self-contained.
pub const COMPONENTS_JSON: &str = include_str!("../data/components.json");
/// The customization guide (copy of `crates/glowkit/docs/CUSTOMIZING.md`).
pub const CUSTOMIZING_MD: &str = include_str!("../data/CUSTOMIZING.md");
/// The component conventions (copy of `CONTRIBUTING.md`).
pub const CONVENTIONS_MD: &str = include_str!("../data/CONVENTIONS.md");

#[derive(Debug, Deserialize)]
pub struct Catalog {
    pub glowkit_version: String,
    pub egui_version: String,
    pub categories: Vec<Category>,
    pub components: Vec<Component>,
    pub types: BTreeMap<String, TypeApi>,
    pub theme: ThemeData,
}

#[derive(Debug, Deserialize)]
pub struct Category {
    pub name: String,
    pub count: usize,
    pub features: Vec<String>,
    pub examples: Vec<String>,
}

#[derive(Debug, Deserialize)]
pub struct Component {
    pub id: String,
    pub name: String,
    pub category: String,
    pub description: String,
    pub covers: Vec<String>,
    pub code: String,
    pub showcase: bool,
    #[serde(rename = "crate")]
    pub crate_name: String,
    pub feature: String,
    pub module: String,
    /// Key into [`Catalog::types`] of the main type the demo uses.
    #[serde(rename = "type")]
    pub type_key: Option<String>,
    /// Compiler-verified `use` paths for every glowkit item the snippet uses.
    #[serde(rename = "use")]
    pub use_paths: Vec<String>,
    pub template: bool,
    pub related: Vec<String>,
    /// Variables the snippet keeps across frames (become fields of the app struct).
    #[serde(default)]
    pub state: Vec<StateVar>,
}

#[derive(Debug, Deserialize)]
pub struct StateVar {
    pub name: String,
    /// Inferred Rust type (from the receiving parameter or the initializer).
    #[serde(rename = "type")]
    pub ty: Option<String>,
    /// Initializer from the snippet's `let mut name = init;`, if any.
    pub init: Option<String>,
    /// The exact declaration statement in the snippet.
    pub decl: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct TypeApi {
    pub name: String,
    pub kind: String,
    pub doc: String,
    pub example: Option<String>,
    pub source: String,
    pub constructors: Vec<Method>,
    pub setters: Vec<Method>,
    pub methods: Vec<Method>,
    pub fields: Vec<Field>,
    pub variants: Vec<String>,
    pub widget: bool,
    pub path: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct Method {
    pub sig: String,
    pub doc: String,
}

#[derive(Debug, Deserialize)]
pub struct Field {
    pub name: String,
    #[serde(rename = "type")]
    pub ty: String,
    pub doc: String,
}

#[derive(Debug, Deserialize)]
pub struct ThemeData {
    pub doc: String,
    pub fields: Vec<Field>,
    pub presets: Vec<Preset>,
    pub methods: Vec<Method>,
}

#[derive(Debug, Deserialize)]
pub struct Preset {
    #[serde(rename = "fn")]
    pub func: String,
    pub doc: String,
    pub values: BTreeMap<String, serde_json::Value>,
}

impl Catalog {
    pub fn component(&self, id: &str) -> Option<&Component> {
        let id = id.trim().trim_start_matches('#');
        self.components
            .iter()
            .find(|c| c.id == id)
            .or_else(|| self.components.iter().find(|c| c.name.eq_ignore_ascii_case(id)))
            .or_else(|| {
                // Accept a type name too ("ShinyText", "glowkit::text::ShinyText").
                let name = id.rsplit("::").next().unwrap_or(id);
                self.components.iter().find(|c| c.type_key.as_deref().and_then(|k| k.rsplit("::").next()) == Some(name))
            })
    }

    pub fn type_api(&self, c: &Component) -> Option<&TypeApi> {
        c.type_key.as_deref().and_then(|k| self.types.get(k))
    }
}

/// The catalog, parsed once.
pub fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| serde_json::from_str(COMPONENTS_JSON).expect("embedded components.json is valid"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_loads_and_is_consistent() {
        let c = catalog();
        assert!(c.components.len() > 500, "expected the full gallery");
        assert!(!c.categories.is_empty());
        for comp in &c.components {
            if let Some(k) = &comp.type_key {
                assert!(c.types.contains_key(k), "{} references missing type {k}", comp.id);
            }
            for r in &comp.related {
                assert!(c.component(r).is_some(), "{} has unknown related {r}", comp.id);
            }
        }
        assert!(c.theme.presets.iter().any(|p| p.func == "dark"));
    }

    #[test]
    fn lookup_by_id_name_and_type() {
        let c = catalog();
        assert_eq!(c.component("shiny-text").unwrap().id, "shiny-text");
        assert_eq!(c.component("Shiny Text").unwrap().id, "shiny-text");
        assert_eq!(c.component("glowkit::text::ShinyText").unwrap().id, "shiny-text");
        assert!(c.component("no-such-thing").is_none());
    }
}
